请对以下 case 进行三维加权评分。

=== case_id ===
Case-06-memory-clean-119

=== 用户原始指令 (query.txt) ===
手机内存满了老是崩溃，我要弄个从风景图延伸出天空配色的卡片，不要放任何图片，纯文字和色块就行。横着排三个环形进度条分别显示“总容量”、“已用”、“剩余”，每个上面标个静态的说明文字，内存那条要是红色的显示“告警状态”，再加个清理图标的元素，点一下就能跳到系统的应用管理里面去。

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "手机内存满了老是崩溃，我要弄个从风景图延伸出天空配色的卡片，不要放任何图片，纯文字和色块就行。横着排三个环形进度条分别显示“总容量”、“已用”、“剩余”，每个上面标个静态的说明文字，内存那条要是红色的显示“告警状态”，再加个清理图标的元素，点一下就能跳到系统的应用管理里面去。",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.android.settings",
        "abilityName": "com.android.settings.applications.ManageApplications",
        "uri": "settings://applications/manage"
      }
    }
  ],
  "dataModel": {
    "value": {
      "memory": {
        "total": {
          "label": "总容量",
          "value": 128,
          "total": 128,
          "display": "128G"
        },
        "used": {
          "label": "已用",
          "value": 116,
          "total": 128,
          "display": "116G",
          "status": "告警状态"
        },
        "free": {
          "label": "剩余",
          "value": 12,
          "total": 128,
          "display": "12G"
        },
        "actionText": "清理",
        "iconText": "C"
      }
    }
  },
  "assetCandidates": []
}

